import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { extractLiveExports } from "./public-export-surface-verifier.js";

function basenameFromTarget(targetRel: string): string {
  return path.basename(targetRel, path.extname(targetRel));
}

function renderMarkdown(targetRel: string, rows: ReturnType<typeof extractLiveExports>): string {
  const lines = [
    `# Public Export Surface — ${targetRel}`,
    "",
    "Generated by `scripts/architecture/extract-public-export-surface.ts`. Do not edit by hand.",
    "",
    `Export count: ${rows.size}`,
    "",
    "| exportName | kind | signature |",
    "| --- | --- | --- |",
  ];

  for (const row of [...rows.values()].toSorted((a, b) =>
    a.exportName.localeCompare(b.exportName),
  )) {
    const signature = row.signature.replace(/\|/g, "\\|");
    lines.push(`| ${row.exportName} | ${row.kind} | ${signature} |`);
  }

  lines.push("");
  return lines.join("\n");
}

function main(): void {
  const targetArg = process.argv[2];
  if (!targetArg) {
    console.error("Usage: pnpm baseline:export-surface <repo-relative-target.ts>");
    process.exit(1);
  }

  const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
  const targetRel = targetArg.replace(/\\/g, "/");
  const targetAbs = path.resolve(repoRoot, targetRel);
  const rows = extractLiveExports(targetAbs);
  const outPath = path.join(
    repoRoot,
    ".kiro/specs/gateway-plugins-monolith-decomposition/baseline",
    `${basenameFromTarget(targetRel)}.md`,
  );

  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, renderMarkdown(targetRel, rows), "utf8");
  console.log(`Wrote ${path.relative(repoRoot, outPath)} (${rows.size} exports)`);
}

const scriptPath = fileURLToPath(import.meta.url);
if (process.argv[1] && path.resolve(process.argv[1]) === scriptPath) {
  main();
}
